    """
    Compares two numbers, ignoring commas, returns larger or None.

    Args:
        a: First number (int, float, or string representation)
        b: Second number (int, float, or string representation)

    Returns:
        The larger number as a float, or None if they are equal
    """
    def parse_number(value):
        """Parse a number string, removing commas."""
        if isinstance(value, (int, float)):
            return float(value)
        elif isinstance(value, str):
            # Remove commas and whitespace, then convert to float
            cleaned = value.replace(',', '').strip()
            return float(cleaned)
        else:
            raise ValueError(f"Unsupported type: {type(value)}")

