def is_monotonic(sequence):
    """Check if the list is entirely non-decreasing or non-increasing."""
    if not sequence:
        return True

    # Determine direction based on the first distinct adjacent pair
    direction = 0
    for i in range(len(sequence) - 1):
        if sequence[i] < sequence[i + 1]:
            direction = 1
            break
        elif sequence[i] > sequence[i + 1]:
            direction = -1
            break

    # If all elements are equal, it's both non-decreasing and non-increasing
    if direction == 0:
        return True

    # Check the rest of the list against the determined direction
    for i in range(len(sequence) - 1):
        if direction == 1 and sequence[i] > sequence[i + 1]:
            return False
        elif direction == -1 and sequence[i] < sequence[i + 1]:
            return False

    return True

